package com.codepathacademy.learning;

import com.codepathacademy.curriculum.CurriculumClass;import com.codepathacademy.identity.AppUser;import com.codepathacademy.identity.UserRepository;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.persistence.EntityManager;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;

@Service @Transactional public class LearningDataImportService {
 private final UserRepository users;private final EntityManager entities;private final PersonalNoteRepository notes;private final ClassProgressRepository progress;private final LearningDataImportRepository imports;private final ConflictResolutionRepository resolutions;private final ObjectMapper json;
 public LearningDataImportService(UserRepository users,EntityManager entities,PersonalNoteRepository notes,ClassProgressRepository progress,LearningDataImportRepository imports,ConflictResolutionRepository resolutions,ObjectMapper json){this.users=users;this.entities=entities;this.notes=notes;this.progress=progress;this.imports=imports;this.resolutions=resolutions;this.json=json;}
 @Transactional(readOnly=true) public Result preview(String userId,Payload payload){validate(payload);return evaluate(user(userId),payload);}
 public ImportedResult importData(String userId,String key,Payload payload){validate(payload);if(key==null||!key.matches("[A-Za-z0-9._-]{8,80}"))throw new IllegalArgumentException("A valid import key is required");var user=user(userId);var fingerprint=fingerprint(payload);var sameKey=imports.findByUserIdAndImportKey(user.getId(),key);if(sameKey.isPresent()){if(!sameKey.get().getFingerprint().equals(fingerprint))throw new NotesService.ConflictException("This import key was already used with different data.");return new ImportedResult(sameKey.get().getId(),true,read(sameKey.get().getSummary()));}var prior=imports.findByUserIdAndFingerprint(user.getId(),fingerprint);if(prior.isPresent())return new ImportedResult(prior.get().getId(),true,read(prior.get().getSummary()));var result=evaluate(user,payload);for(Item item:result.items()){if(item.kind().equals("note")&&item.status().equals("eligible")){var c=clazz(item.code());notes.save(new PersonalNote(user,c,null,"Legacy note · "+item.code(),item.value(),item.value(),null,"legacy:"+item.sourceKey()));}if(item.kind().equals("progress")&&item.status().equals("eligible")){var c=clazz(item.code());progress.save(new ClassProgress(user,c,ProgressState.STUDIED));}}var audit=imports.save(new LearningDataImport(user,fingerprint,key,write(result)));return new ImportedResult(audit.getId(),false,result);}
 @Transactional(readOnly=true) public ImportedResult get(String userId,UUID id){var audit=imports.findByIdAndUserId(id,user(userId).getId()).orElseThrow(()->new NoSuchElementException("Import not found"));return new ImportedResult(audit.getId(),true,read(audit.getSummary()));}
 public ResolutionResult resolve(String userId,UUID importId,String sourceKey,ResolutionRequest request){var user=user(userId);if(request==null||request.idempotencyKey()==null||!request.idempotencyKey().matches("[A-Za-z0-9._-]{8,80}"))throw new IllegalArgumentException("A valid resolution key is required");var prior=resolutions.findByUserIdAndOperationKey(user.getId(),request.idempotencyKey());if(prior.isPresent())return new ResolutionResult(prior.get().resolution,prior.get().note==null?null:prior.get().note.getId(),true);var audit=imports.findByIdAndUserId(importId,user.getId()).orElseThrow(()->new NoSuchElementException("Import not found"));var item=read(audit.getSummary()).items().stream().filter(i->i.kind().equals("note")&&i.status().equals("conflict")&&i.sourceKey().equals(sourceKey)).findFirst().orElseThrow(()->new NoSuchElementException("Conflict not found"));var c=clazz(item.code());var server=notes.findByUserIdAndCurriculumClassIdAndDeletedAtIsNull(user.getId(),c.getId()).stream().findFirst().orElseThrow(()->new NoSuchElementException("Server note not found"));var same=resolutions.findByImportAuditIdAndSourceKeyAndResolution(importId,sourceKey,request.resolution());if(same.isPresent())return new ResolutionResult(same.get().resolution,same.get().note==null?null:same.get().note.getId(),true);PersonalNote target=server;if(request.resolution().equals("SAVE_AS_COPY")){target=notes.saveAndFlush(new PersonalNote(user,c,null,"Migrated copy · "+c.getCode(),item.value(),item.value(),null,"resolution:"+importId+":"+sourceKey));}else if(request.resolution().equals("REPLACE_SERVER")){if(request.expectedServerRevision()==null||server.getVersion()!=request.expectedServerRevision())throw new NotesService.ConflictException("Server note changed; review it again before replacing.");entities.createNativeQuery("insert into note_revisions(note_id,body,body_en,body_ml,version) values (?1,?2,?3,?4,?5)").setParameter(1,server.getId()).setParameter(2,server.getBody()).setParameter(3,server.getBodyEn()).setParameter(4,server.getBodyMl()).setParameter(5,server.getVersion()).executeUpdate();server.update(c,null,server.getTitle(),item.value(),item.value(),null);target=notes.saveAndFlush(server);}else if(!request.resolution().equals("KEEP_SERVER"))throw new IllegalArgumentException("Unsupported resolution");resolutions.save(new ConflictResolution(audit,user,sourceKey,request.idempotencyKey(),request.resolution(),target,request.expectedServerRevision()));return new ResolutionResult(request.resolution(),target.getId(),false);}
 private Result evaluate(AppUser user,Payload p){var items=new ArrayList<Item>();for(var entry:p.data().notes().entrySet()){var code=code(entry.getKey());if(code==null)items.add(new Item("note",entry.getKey(),null,"unmapped","Invalid legacy note key",null));else if(entry.getValue()==null||entry.getValue().length()>50000)items.add(new Item("note",entry.getKey(),code,"invalid","Note content is invalid",null));else if(clazz(code)==null)items.add(new Item("note",entry.getKey(),code,"unmapped","Class is not in the curriculum",null));else if(notes.existsByUserIdAndCurriculumClassIdAndDeletedAtIsNull(user.getId(),clazz(code).getId()))items.add(new Item("note",entry.getKey(),code,"conflict","An account note already exists for this class",null));else items.add(new Item("note",entry.getKey(),code,"eligible",null,entry.getValue()));}for(Integer value:p.data().progress()){var code=code(value);if(code==null)items.add(new Item("progress",String.valueOf(value),null,"unmapped","Invalid completion marker",null));else if(clazz(code)==null)items.add(new Item("progress",String.valueOf(value),code,"unmapped","Class is not in the curriculum",null));else {var existing=progress.findByUserIdAndCurriculumClassId(user.getId(),clazz(code).getId());items.add(new Item("progress",String.valueOf(value),code,existing.isPresent()?"duplicate":"eligible",existing.isPresent()?"Account progress already exists":null,null));}}return new Result(items,(long)items.stream().filter(i->i.status().equals("eligible")).count(),(long)items.stream().filter(i->i.status().equals("conflict")).count(),(long)items.stream().filter(i->i.status().equals("duplicate")).count(),(long)items.stream().filter(i->i.status().equals("unmapped")||i.status().equals("invalid")).count());}
 private String code(Object legacy){try{String s=String.valueOf(legacy);String[] parts=s.contains("-")?s.split("-"):new String[]{String.valueOf(Integer.parseInt(s)/10),String.valueOf(Integer.parseInt(s)%10)};int week=Integer.parseInt(parts[0]),slot=Integer.parseInt(parts[1]);return week>=1&&week<=40&&slot>=1&&slot<=5?String.format("CPA-W%02d-C%02d",week,slot):null;}catch(Exception ignored){return null;}}
 private CurriculumClass clazz(String code){return code==null?null:entities.createQuery("select c from CurriculumClass c where c.code=:code",CurriculumClass.class).setParameter("code",code).getResultStream().findFirst().orElse(null);}private AppUser user(String id){return users.findById(UUID.fromString(id)).orElseThrow(()->new NoSuchElementException("User not found"));}private void validate(Payload p){if(p==null||p.schemaVersion()!=1||p.data()==null||p.data().notes()==null||p.data().progress()==null||p.data().notes().size()>500||p.data().progress().size()>500)throw new IllegalArgumentException("Unsupported or oversized learning-data backup");}private String fingerprint(Payload p){try{var digest=MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(p));return java.util.HexFormat.of().formatHex(digest);}catch(Exception e){throw new IllegalStateException("Cannot fingerprint import",e);}}private String write(Result r){try{return json.writeValueAsString(r);}catch(Exception e){throw new IllegalStateException("Cannot store import summary",e);}}private Result read(String v){try{return json.readValue(v,Result.class);}catch(Exception e){throw new IllegalStateException("Cannot read import summary",e);}}
 public record Payload(int schemaVersion,String exportedAt,String source,Data data){}public record Data(String language,List<Integer> progress,Map<String,String> notes){}public record Item(String kind,String sourceKey,String code,String status,String reason,String value){}public record Result(List<Item> items,long eligible,long conflicts,long duplicates,long unmapped){}public record ImportedResult(UUID importId,boolean alreadyImported,Result result){}
 public record ResolutionRequest(String resolution,Long expectedServerRevision,String idempotencyKey){}public record ResolutionResult(String resolution,UUID noteId,boolean alreadyResolved){}
}
